query.value:
@{
    if(
        contains(json(item().source_property).query, '{watermark_value}'),
        replace(
            replace(
                json(item().source_property).query,
                '{watermark_value}',
                concat('''', item().watermark_value, '''')
            ),
            '{max_timestamp}',
            concat('''', activity('LkpSapTable').output.firstRow.updated_time, '''')
        ),
        json(item().source_property).query
    )
}
